273	const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };
274	
275	/**
276	 * Shared responsive email shell (inline styles for client compatibility).
277	 * Kept for the synchronous, code-rendered `emails.*` templates below and any
278	 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
279	 */
280	export function layout(title: string, body: string): string {
281	  // Delegate to the shared premium shell so every email is consistent.
282	  const heading = title
283	    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
284	    : "";
285	  return wrapEmail(`${heading}<div>${body}</div>`);
286	}
287	
288	export function button(href: string, label: string): string {
289	  return emailButton(href, label);
290	}
291	
292	// ---- Transactional templates ----
293	//
294	// The full transactional catalog lives in `lib/email-templates.ts` (30+
295	// templates, all composed from the shared inline-styled components). It is
296	// re-exported here as `emails` so every existing call site — `import { emails }
297	// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
298	// `{ template, subject, html }`; the six original signatures are preserved.
299	export type { BuiltEmail };
300	
301	// ===========================================================================
302	// Card billing & dunning templates
303	//
304	// Renewals apply wallet credit first, then auto-charge the customer's saved
305	// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
306	// only suspend once the retries are exhausted. These templates carry that flow.
307	//
308	// They live here rather than in `lib/email-templates.ts` only because this file
309	// is the one owned by the card-billing change; they are built with the same
310	// `build()` shape and the same shared components, so they render identically to
311	// the rest of the catalog.
312	// ===========================================================================
313	
314	/**
315	 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
316	 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
317	 * so the worker's retry schedule and this copy must agree.
318	 */
319	export const DUNNING_RETRY_ATTEMPTS = 3;
320	
321	/**
322	 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
323	 * module-private): eyebrow → heading → body blocks → single CTA → optional
324	 * footnote, wrapped with a preheader by the shared shell.
325	 */
326	function build(opts: {
327	  template: string;
328	  subject: string;
329	  preheader: string;
330	  eyebrow?: string;
331	  accent?: Accent;
332	  heading: string;
333	  blocks: string[];
334	  cta?: { href: string; label: string; accent?: Accent };
335	  note?: string;
336	}): BuiltEmail {
337	  const parts: string[] = [];
338	  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
339	  parts.push(emailHeading(opts.heading));
340	  parts.push(...opts.blocks);
341	  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
342	  if (opts.note) parts.push(emailNote(opts.note));
343	  return {
344	    template: opts.template,
345	    subject: opts.subject,
346	    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
347	  };
348	}
349	
350	/** Masked card display used wherever we echo the saved card back. */
351	const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;
352	
353	/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
354	const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;
355	
356	/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
357	const stillRunning = (hostname: string, extra = "") =>
358	  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");
359	
360	const legacyPaymentFailed = catalogEmails.paymentFailed;
361	type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];
362	
363	/**
364	 * Card charge declined — FIRST failure of the dunning sequence.
365	 *
366	 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
367	 * still used by the admin template previewer) keeps working alongside the new
368	 * renewal-dunning shape.
369	 */
370	function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
371	function paymentFailed(
372	  hostname: string,
373	  amountFormatted: string,
374	  last4: string,
375	  retryDateFormatted: string,
376	  billingUrl: string,
377	): BuiltEmail;
378	function paymentFailed(
379	  a: string | LegacyPaymentFailedArgs,
380	  amountFormatted?: string,
381	  last4?: string,
382	  retryDateFormatted?: string,
383	  billingUrl?: string,
384	): BuiltEmail {
385	  if (typeof a !== "string") return legacyPaymentFailed(a);
386	  const hostname = a;
387	  const amount = amountFormatted ?? "";
388	  const card = last4 ?? "";
389	  const retryDate = retryDateFormatted ?? "";
390	  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
391	  return build({
392	    template: "payment_failed",
393	    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
394	    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
395	    eyebrow: "Payment issue",
396	    accent: "warn",
397	    heading: "We couldn't charge your card",
398	    blocks: [
399	      emailParagraph(
400	        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
401	      ),
402	      stillRunning(hostname),
403	      emailPanel(
404	        emailKeyValue([
405	          ["Server", hostname],
406	          ["Amount due", amount],
407	          ["Card", cardLabel(card)],
408	          ["Next attempt", retryDate],
409	        ]),
410	        "warn",
411	      ),
412	      emailParagraph(
413	        `We'll try the same card again on <b>${retryDate}</b>. If you'd rather not wait, update your card and we'll charge it straight away.`,
414	      ),
415	    ],
416	    cta: { href, label: "Update payment method", accent: "warn" },
417	    note: "If your bank asked you to approve the charge, approving it is enough. Anything else — just reply to this email and our team will take a look.",
418	  });
419	}
420	
421	const billingEmails = {
422	  /** Successful auto-charge against the saved card. */
423	  paymentReceipt: (amountFormatted: string, description: string, last4: string): BuiltEmail =>
424	    build({
425	      template: "payment_receipt",
426	      subject: `Receipt for ${amountFormatted} — card ending ${last4}`,
427	      preheader: `We charged ${amountFormatted} to your saved card. Everything is running as normal.`,
428	      eyebrow: "Receipt",
429	      accent: "success",
430	      heading: "Payment received",
431	      blocks: [
432	        emailParagraph(
433	          "Your renewal has been paid automatically using the card saved on your account. Everything is running as normal — there's nothing you need to do.",
434	        ),
435	        emailPanel(
436	          emailKeyValue([
437	            ["Amount", `<span style="color:#15a34a;">${amountFormatted}</span>`],
438	            ["For", description],
439	            ["Card", cardLabel(last4)],
440	          ]),
441	          "success",
442	        ),
443	        emailParagraph("Any wallet credit on your account was applied first; the amount above is what we charged to the card."),
444	      ],
445	      cta: { href: `${appUrl()}/dashboard/invoices`, label: "View invoices" },
446	      note: "Keep this email for your records, or download the itemised invoice from your dashboard at any time.",
447	    }),
448	
449	  /** First declined charge in the dunning sequence (see the overloads above). */
450	  paymentFailed,
451	
452	  /** A later retry in the dunning sequence was declined. */
453	  paymentRetryFailed: (
454	    hostname: string,
455	    amountFormatted: string,
456	    attempt: number,
457	    finalDateFormatted: string,
458	    billingUrl: string,
459	  ): BuiltEmail => {
460	    const remaining = Math.max(0, DUNNING_RETRY_ATTEMPTS - attempt);
461	    const remainingLine =
462	      remaining > 0
463	        ? `We'll try ${remaining} more time${remaining === 1 ? "" : "s"} before then.`
464	        : "That was the last automatic attempt.";
465	    return build({
466	      template: "payment_retry_failed",
467	      subject: `Payment retry ${attempt} declined for ${hostname} — still running until ${finalDateFormatted}`,
468	      preheader: `${hostname} stays online until ${finalDateFormatted}. ${remainingLine}`,
469	      eyebrow: `Retry ${attempt} declined`,
470	      accent: "warn",
471	      heading: "Your card was declined again",
472	      blocks: [
473	        emailParagraph(
474	          `We tried the saved card for <b>${hostname}</b> again and it was declined. If the card is fine on your end, it's worth asking your bank whether they're blocking the charge — that's the usual cause at this stage.`,
475	        ),
476	        stillRunning(hostname, `It stays online until <b>${finalDateFormatted}</b>.`),
477	        emailPanel(
478	          emailKeyValue([
479	            ["Server", hostname],
480	            ["Amount due", amountFormatted],
481	            ["Attempt", String(attempt)],
482	            ["Attempts remaining", String(remaining)],
483	            ["Suspends on", finalDateFormatted],
484	          ]),
485	          "warn",
486	        ),
487	        emailParagraph(
488	          `${remainingLine} If the balance is still unpaid on <b>${finalDateFormatted}</b>, <b>${hostname}</b> will be suspended — your data stays intact and paying restores it.`,
489	        ),
490	        emailParagraph("Updating your card now settles the balance immediately and stops the remaining retries."),
491	      ],
492	      cta: { href: billingUrl, label: "Update payment method", accent: "warn" },
493	      note: "If something about this charge looks wrong, or you need a little more time, reply to this email — we'd rather work it out with you.",
494	    });
495	  },
496	
497	  /** Stripe returned `requires_action` — the customer must complete 3-D Secure. */
498	  paymentActionRequired: (hostname: string, amountFormatted: string, authUrl: string): BuiltEmail =>
499	    build({
500	      template: "payment_action_required",
501	      subject: `Confirm the ${amountFormatted} payment for ${hostname} with your bank`,
502	      preheader: `${hostname} is still running. Your bank needs one quick confirmation to finish the payment.`,
503	      eyebrow: "Confirmation needed",
504	      accent: "info",
505	      heading: "Your bank needs to confirm this payment",
506	      blocks: [
507	        emailParagraph(
508	          `Your card issuer asked for an extra verification step before the renewal payment for <b>${hostname}</b> can complete. This is a routine security check on their side, and it takes less than a minute.`,
509	        ),
510	        stillRunning(hostname, "Confirming the payment keeps it that way."),
511	        emailPanel(
512	          emailKeyValue([
513	            ["Server", hostname],
514	            ["Amount", amountFormatted],
515	            ["Waiting on", "Bank confirmation (3-D Secure)"],
516	          ]),
517	        ),
518	        emailParagraph("Use the button below to confirm with your bank. We'll finish the payment as soon as they approve it."),
519	      ],
520	      cta: { href: authUrl, label: "Confirm payment with your bank" },
521	      note: `This confirmation link is unique to this payment and expires after a short while. If it's already expired, open <a href="${appUrl()}/dashboard/billing" style="color:#6f47f5;">Billing</a> and we'll start a fresh attempt.`,
522	    }),
523	
524	  /** Final retry failed — the last warning before the server is suspended. */
525	  paymentFinalNotice: (hostname: string, amountFormatted: string, billingUrl: string): BuiltEmail =>
526	    build({
527	      template: "payment_final_notice",
528	      subject: `Final notice for ${hostname} — ${amountFormatted} still unpaid`,
529	      preheader: `${hostname} is still running, but this is the last notice before it's suspended.`,
530	      eyebrow: "Final notice",
531	      accent: "danger",
532	      heading: "Last notice before suspension",
533	      blocks: [
534	        emailParagraph(
